public class VolatileSafePublication {
    private volatile boolean initialized = false;
    private int[] data;

    public void writer() {
        data = new int[]{1, 2, 3, 4, 5}; // Normal write
        initialized = true;             // Volatile write (acts as a StoreStore and StoreLoad barrier)
    }

    public void reader() {
        if (initialized) {              // Volatile read (acts as a LoadLoad and LoadStore barrier)
            // Safe to read data; the JMM guarantees the array write is visible
            System.out.println(data[0]);
        }
    }
}
